using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace BlockArena.Runtime
{
    // Original PCM resources are generated by Tools/Generate-ArenaAudio.py.
    // Music shares a tempo and phrase length so changing phase preserves the beat.
    public sealed class ArenaAudio : MonoBehaviour
    {
        const string ResourceRoot = "ArenaAudio/";
        const string MusicPreference = "arena.audio.music";
        const string SfxPreference = "arena.audio.sfx";
        const string MutePreference = "arena.audio.muted";
        const int NormalVoiceCount = 8;
        const int VoiceCount = 10;
        const float CrossfadeSeconds = .85f;

        static ArenaAudio instance;
        readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>(StringComparer.Ordinal);
        readonly Dictionary<string, Cue> cues = new Dictionary<string, Cue>(StringComparer.Ordinal);
        readonly Dictionary<string, float> nextCueTime = new Dictionary<string, float>(StringComparer.Ordinal);
        readonly AudioSource[] musicSources = new AudioSource[2];
        readonly AudioSource[] voices = new AudioSource[VoiceCount];
        readonly float[] voiceUntil = new float[VoiceCount];
        readonly int[] voicePriority = new int[VoiceCount];
        readonly float[] voiceLevels = new float[VoiceCount];
        readonly float[] musicWeights = new float[2];
        readonly float[] fadeFrom = new float[2];

        float musicVolume, sfxVolume, fadeStarted, saveAt, nextListenerCheck;
        double musicEpoch;
        int activeMusic, variant;
        bool muted, preferencesDirty, fading;
        AudioListener fallbackListener;
        string currentMusic = "";

        public float MusicVolume { get { return musicVolume; } }
        public float SfxVolume { get { return sfxVolume; } }
        public bool Muted { get { return muted || (musicVolume <= 0 && sfxVolume <= 0); } }
        public int SoundCount { get; private set; }
        public int ClipsLoaded { get { return clips.Count; } }
        public int MusicTrackCount { get; private set; }
        public string CurrentMusic { get { return currentMusic; } }
        public bool MusicIsPlaying
        {
            get
            {
                return (musicSources[0] != null && musicSources[0].isPlaying) ||
                    (musicSources[1] != null && musicSources[1].isPlaying);
            }
        }

        sealed class Cue
        {
            public string clip;
            public float gain, cooldown, spatial;
            public int priority;
            public bool fixedPitch;
        }

        public static ArenaAudio Initialize()
        {
            string[] args = Environment.GetCommandLineArgs();
            if (Application.isBatchMode || SystemInfo.graphicsDeviceType == GraphicsDeviceType.Null ||
                Array.IndexOf(args, "-arena-server") >= 0) return null;
            if (instance != null) return instance;
            return new GameObject("Arena Audio").AddComponent<ArenaAudio>();
        }

        void Awake()
        {
            if (instance != null && instance != this) { Destroy(gameObject); return; }
            instance = this;
            DontDestroyOnLoad(gameObject);
            musicVolume = Mathf.Clamp01(PlayerPrefs.GetFloat(MusicPreference, .4f));
            sfxVolume = Mathf.Clamp01(PlayerPrefs.GetFloat(SfxPreference, .65f));
            muted = PlayerPrefs.GetInt(MutePreference, 0) != 0;
            for (int i = 0; i < musicSources.Length; i++)
            {
                musicSources[i] = MakeSource("Music " + i);
                musicSources[i].loop = true;
                musicSources[i].priority = 32;
                musicSources[i].volume = 0;
            }
            for (int i = 0; i < voices.Length; i++) voices[i] = MakeSource("Effect " + i);
            LoadMusic("music_menu"); LoadMusic("music_prep"); LoadMusic("music_battle");
            Register("click", .58f, .045f, 0, 1, true);
            Register("purchase", .70f, .09f, 0, 2, true);
            Register("coin", .53f, .12f, 0, 1, false);
            Register("pickup", .58f, .075f, .12f, 1, false);
            Register("place", .63f, .075f, .12f, 1, false);
            Register("recruit", .58f, .6f, 0, 2, true);
            Register("battle_start", .77f, .8f, 0, 3, true);
            Register("attack", .22f, .11f, .12f, 0, false);
            Register("ritual_rise", .76f, .25f, .08f, 4, true);
            Register("ritual_charge", .64f, .2f, .08f, 4, true);
            Register("ritual_launch", .80f, .13f, .08f, 4, false);
            Register("commander_hit", .82f, .13f, .08f, 5, false);
            Register("victory", .78f, 1f, 0, 5, true);
            Register("defeat", .70f, 1f, 0, 5, true);
            Register("combat_arrow", .20f, .12f, .12f, 0, false);
            Register("combat_hit", .19f, .10f, .12f, 0, false);
            Register("combat_explode", .28f, .18f, .12f, 1, false);
            Register("combat_death", .22f, .14f, .12f, 0, false);
            Register("combat_heal", .25f, .16f, .12f, 0, false);
            Register("error", .40f, .2f, 0, 1, true);
            Alias("ui_click", "click"); Alias("buy", "purchase"); Alias("gold", "coin");
            Alias("drag", "pickup"); Alias("drop", "place"); Alias("start", "battle_start");
            Alias("win", "victory"); Alias("lose", "defeat");
            Alias("open", "pickup"); Alias("close", "place"); Alias("ready", "click");
            Alias("refresh", "coin"); Alias("choose", "purchase"); Alias("skip", "click");
            Alias("ui_open", "pickup"); Alias("ui_close", "place"); Alias("battle", "battle_start");
            musicEpoch = AudioSettings.dspTime + .05;
            CheckListener();
            SetPhase("menu");
        }

        AudioSource MakeSource(string sourceName)
        {
            var child = new GameObject(sourceName);
            child.transform.SetParent(transform, false);
            var source = child.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.spatialBlend = 0;
            source.dopplerLevel = 0;
            source.rolloffMode = AudioRolloffMode.Linear;
            source.minDistance = 12;
            source.maxDistance = 180;
            source.reverbZoneMix = 0;
            return source;
        }

        AudioClip LoadClip(string name)
        {
            AudioClip clip;
            if (clips.TryGetValue(name, out clip)) return clip;
            clip = Resources.Load<AudioClip>(ResourceRoot + name);
            if (clip == null)
            {
                Debug.LogWarning("Arena audio resource missing: " + ResourceRoot + name);
                return null;
            }
            clips.Add(name, clip);
            return clip;
        }

        void LoadMusic(string name)
        {
            if (LoadClip(name) != null) MusicTrackCount++;
        }

        void Register(string name, float gain, float cooldown, float spatial, int priority, bool fixedPitch)
        {
            if (LoadClip(name) == null) return;
            cues.Add(name, new Cue { clip = name, gain = gain, cooldown = cooldown,
                spatial = spatial, priority = priority, fixedPitch = fixedPitch });
        }

        void Alias(string name, string original)
        {
            Cue cue;
            if (cues.TryGetValue(original, out cue)) cues[name] = cue;
        }

        public void SetPhase(string phase)
        {
            string track = phase == "battle" ? "music_battle" :
                phase == "prep" || phase == "recruit" || phase == "results" ? "music_prep" : "music_menu";
            if (currentMusic == track) return;
            AudioClip clip;
            if (!clips.TryGetValue(track, out clip)) return;
            int destination = string.IsNullOrEmpty(currentMusic) ? 0 : 1 - activeMusic;
            AudioSource source = musicSources[destination];
            source.Stop();
            source.clip = clip;
            // All three themes have exactly the same 16-bar phrase length.
            double start = AudioSettings.dspTime + .05;
            double phrase = (double)clip.samples / clip.frequency;
            double position = (start - musicEpoch) % phrase;
            if (position < 0) position += phrase;
            source.timeSamples = Math.Min(clip.samples - 1, (int)(position * clip.frequency));
            source.volume = 0;
            source.PlayScheduled(start);
            for (int i = 0; i < fadeFrom.Length; i++) fadeFrom[i] = musicWeights[i];
            fadeFrom[destination] = 0;
            activeMusic = destination;
            fadeStarted = Time.unscaledTime + .05f;
            fading = true;
            currentMusic = track;
        }

        public void SetVolumes(float music, float sfx, bool muted = false)
        {
            musicVolume = Mathf.Clamp01(float.IsNaN(music) ? .4f : music);
            sfxVolume = Mathf.Clamp01(float.IsNaN(sfx) ? .65f : sfx);
            this.muted = muted;
            preferencesDirty = true;
            saveAt = Time.unscaledTime + .45f;
            ApplyVolumes();
        }

        public void Play(string cue, Vector3 world, float intensity = 1f)
        {
            if (muted || sfxVolume <= 0 || string.IsNullOrEmpty(cue)) return;
            Cue definition;
            if (!cues.TryGetValue(cue, out definition)) return;
            float now = Time.unscaledTime;
            float next;
            if (nextCueTime.TryGetValue(definition.clip, out next) && now < next) return;
            AudioClip clip;
            if (!clips.TryGetValue(definition.clip, out clip)) return;
            // Two protected voices retain crystal impacts, commander damage and outcomes.
            // Ordinary attacks only use the eight normal voices.
            int voice = FindVoice(definition.priority, now);
            if (voice < 0) return;
            float level = Mathf.Clamp01(float.IsNaN(intensity) ? 1 : intensity);
            if (level <= 0) return;
            AudioSource source = voices[voice];
            source.Stop();
            source.transform.position = world;
            source.clip = clip;
            source.spatialBlend = 0;
            // The camera is high above the board; 2D playback keeps every tile audible.
            // World effects use only a small screen-relative stereo offset.
            source.panStereo = 0;
            Camera camera = Camera.main;
            if (definition.spatial > 0 && world != Vector3.zero && camera != null)
            {
                Vector3 viewport = camera.WorldToViewportPoint(world);
                source.panStereo = Mathf.Clamp((viewport.x - .5f) * .55f, -.28f, .28f);
            }
            source.priority = Mathf.Clamp(200 - definition.priority * 28, 32, 220);
            // Deterministic local variation never consumes the gameplay random stream.
            variant = (variant + 1) & 1023;
            source.pitch = definition.fixedPitch ? 1 : .96f + ((variant * 37) % 81) * .001f;
            voiceLevels[voice] = definition.gain * level;
            source.volume = voiceLevels[voice] * sfxVolume;
            source.mute = false;
            source.Play();
            voiceUntil[voice] = now + clip.length / source.pitch;
            voicePriority[voice] = definition.priority;
            nextCueTime[definition.clip] = now + definition.cooldown;
            SoundCount++;
        }

        int FindVoice(int priority, float now)
        {
            if (priority >= 3)
            {
                for (int i = NormalVoiceCount; i < VoiceCount; i++)
                    if (voiceUntil[i] <= now || !voices[i].isPlaying) return i;
            }
            for (int i = 0; i < NormalVoiceCount; i++)
                if (voiceUntil[i] <= now || !voices[i].isPlaying) return i;
            int candidate = -1;
            float earliest = float.MaxValue;
            int count = priority >= 3 ? VoiceCount : NormalVoiceCount;
            for (int i = 0; i < count; i++)
            {
                if (voicePriority[i] > priority) continue;
                if (voiceUntil[i] < earliest) { earliest = voiceUntil[i]; candidate = i; }
            }
            return candidate;
        }

        void Update()
        {
            float now = Time.unscaledTime;
            if (fading)
            {
                float t = Mathf.Clamp01((now - fadeStarted) / CrossfadeSeconds);
                // Equal-power fade avoids an audible dip while switching arrangements.
                float incoming = Mathf.Sin(t * Mathf.PI * .5f);
                float outgoing = Mathf.Cos(t * Mathf.PI * .5f);
                for (int i = 0; i < musicSources.Length; i++)
                {
                    musicWeights[i] = i == activeMusic ? incoming : fadeFrom[i] * outgoing;
                    if (t >= 1 && i != activeMusic) musicSources[i].Stop();
                }
                if (t >= 1) fading = false;
            }
            ApplyMusicVolumes();
            if (now >= nextListenerCheck) { CheckListener(); nextListenerCheck = now + 1; }
            if (preferencesDirty && now >= saveAt) SavePreferences();
        }

        void ApplyMusicVolumes()
        {
            for (int i = 0; i < musicSources.Length; i++)
                if (musicSources[i] != null) musicSources[i].volume = muted ? 0 : musicVolume * musicWeights[i];
        }

        void ApplyVolumes()
        {
            ApplyMusicVolumes();
            // Apply slider changes immediately, including a sound already in flight.
            for (int i = 0; i < voices.Length; i++)
                if (voices[i] != null)
                {
                    voices[i].mute = muted || sfxVolume <= 0;
                    voices[i].volume = voiceLevels[i] * sfxVolume;
                }
        }

        void CheckListener()
        {
            bool externalListener = false;
            AudioListener[] listeners = FindObjectsOfType<AudioListener>();
            for (int i = 0; i < listeners.Length; i++)
                if (listeners[i] != fallbackListener && listeners[i].enabled && listeners[i].gameObject.activeInHierarchy)
                { externalListener = true; break; }
            if (!externalListener && fallbackListener == null) fallbackListener = gameObject.AddComponent<AudioListener>();
            if (fallbackListener != null) fallbackListener.enabled = !externalListener;
        }

        void SavePreferences()
        {
            PlayerPrefs.SetFloat(MusicPreference, musicVolume);
            PlayerPrefs.SetFloat(SfxPreference, sfxVolume);
            PlayerPrefs.SetInt(MutePreference, muted ? 1 : 0);
            PlayerPrefs.Save();
            preferencesDirty = false;
        }

        void OnApplicationQuit() { if (preferencesDirty) SavePreferences(); }
        void OnDestroy()
        {
            if (instance != this) return;
            if (preferencesDirty) SavePreferences();
            instance = null;
        }
    }
}
